      <img
        src={image}
        alt={filename ?? "Attached image"}
        className={css({ maxHeight: "20rem", width: "100%", objectFit: "contain" })}
      />
      {filename ? (
        <figcaption
          className={css({
            borderTop: "1px solid var(--border)",
