async function startLiveSession(
	request: LiveSpeechRequest,
	observer?: RealtimeTelemetryObserver,
): Promise<LiveSpeechSession> {
	const { settings, getApiKey, signal, instructions, tools, history, video, onToolCall, onState, onUserTranscript, onAssistantTranscript, onError } = request;
	const telemetry = createRealtimeTelemetry(observer);
	const canonical = createRealtimeCanonicalBridge(request.onConversationEvent, request.conversationIds);
	const setupStartedAt = telemetry.start();
	telemetry.emit("connection.setup.started", {
		provider: "openai",
		model: settings.model || "gpt-realtime-2.1",
		transport: "webrtc",
	});
	const capability = negotiateOpenAIRealtimeSession(settings.model || "gpt-realtime-2.1");
	if (capability.realtimeAudio !== "native" || capability.transport !== "webrtc" || capability.toolCalls !== "native") {
		telemetry.emit("session.error", { provider: "openai", errorCode: "capability_mismatch" });
		telemetry.emit("session.completed", { provider: "openai", outcome: "error" });
		throw new Error(`OpenAI Realtime model ${settings.model} cannot satisfy duplex WebRTC and native tool-call requirements.`);
	}
	// Vision is only offered when the model can actually accept still images;
	// on a legacy preview model the frame sink stays dark rather than erroring.
	const visionEnabled = Boolean(video) && capability.capabilities.realtimeImage === "native";
	canonical.emit("run.started", { mode: visionEnabled ? "multimodal" : "voice" });
	const apiKey = await getApiKey("openai");
	if (!apiKey) {
		const error = new Error("No OpenAI API key configured. Add one in Settings → Providers & Models.");
		telemetry.emit("session.error", { provider: "openai", errorCode: "missing_api_key" });
		telemetry.emit("session.completed", { provider: "openai", outcome: "error" });
		canonical.emit("error", { error: protocolError(error, "missing_api_key"), fatal: true });
		canonical.emit("run.completed", { reason: "error" });
		throw error;
	}

	const model = settings.model || "gpt-realtime-2.1";
	const voice = cleanRealtimeVoice(settings.voiceName);

	let state: LiveSpeechState = "connecting";
	let completionReason: "completed" | "cancelled" | "interrupted" | "error" | null = null;
	let reconnectAttempt = 0;
	let runStarted = true;
	let firstAudioObserved = false;
	let turn = 0;
	let activeTurnStartedAt: number | null = null;
	const toolStartedAt = new Map<string, number>();
	const complete = (reason: NonNullable<typeof completionReason>) => {
		if (completionReason) return;
		completionReason = reason;
		canonical.emit("run.completed", { reason });
		telemetry.emit("session.completed", { provider: "openai", outcome: reason });
	};
	const setState = (next: LiveSpeechState) => {
		if (state === "closed") return;
		state = next;
		onState?.(next);
	};
	setState("connecting");

	let ephemeralKey: string;
	try {
		ephemeralKey = await mintEphemeralKey(apiKey, model, voice, signal);
	} catch (error) {
		telemetry.emit("connection.setup.completed", {
			provider: "openai", model, transport: "webrtc", outcome: "failed",
		}, telemetry.durationSince(setupStartedAt));
		telemetry.emit("session.error", { provider: "openai", errorCode: "ephemeral_key_failed" });
		canonical.emit("error", { error: protocolError(error, "ephemeral_key_failed"), fatal: true });
		complete("error");
		throw error;
	}

	const pc = new RTCPeerConnection();
	const audioEl = typeof document !== "undefined" ? document.createElement("audio") : null;
	if (audioEl) {
		audioEl.autoplay = true;
		audioEl.style.display = "none";
		document.body.appendChild(audioEl);
	}

	let micStream: MediaStream | null = null;
	let cleanedUp = false;
	// Declared before cleanup(), which runs on the abort-before-start path.
	let unsubscribeFrames: (() => void) | null = null;
	let framesSent = 0;
	const cleanup = () => {
		if (cleanedUp) return;
		cleanedUp = true;
		// Only detach from the frame feed; the caller owns the capture handle
		// and may still be rendering a preview from it.
		unsubscribeFrames?.();
		unsubscribeFrames = null;
		try { pc.close(); } catch {}
		micStream?.getTracks().forEach((track) => track.stop());
		if (audioEl) {
			try { audioEl.pause(); } catch {}
			audioEl.srcObject = null;
			audioEl.remove();
		}
		setState("closed");
		complete("cancelled");
	};

	if (signal?.aborted) {
		canonical.emit("conversation.interrupted", { by: "host", reason: "abort signal before start" });
		telemetry.emit("speech.interrupted", { provider: "openai", reason: "abort", turn });
		complete("interrupted");
		cleanup();
		throw new Error("OpenAI Realtime aborted before start.");
	}
	signal?.addEventListener("abort", () => {
		canonical.emit("conversation.interrupted", { by: "host", reason: "abort signal" });
		telemetry.emit("speech.interrupted", { provider: "openai", reason: "abort", turn });
		complete("interrupted");
		cleanup();
	}, { once: true });

	pc.ontrack = (event) => {
		if (audioEl && event.streams[0]) {
			audioEl.srcObject = event.streams[0];
			audioEl.play().catch(() => {});
		}
	};
	pc.addEventListener("connectionstatechange", () => {
		if (!runStarted) return;
		if (pc.connectionState === "disconnected") {
			reconnectAttempt += 1;
			telemetry.emit("reconnect.started", { provider: "openai", attempt: reconnectAttempt });
			canonical.emit("reconnect.started", { attempt: reconnectAttempt, reason: "WebRTC transport disconnected" });
		} else if (pc.connectionState === "connected" && reconnectAttempt > 0) {
			telemetry.emit("reconnect.completed", { provider: "openai", attempt: reconnectAttempt, outcome: "success" });
			canonical.emit("reconnect.succeeded", { attempt: reconnectAttempt });
			reconnectAttempt = 0;
		} else if (pc.connectionState === "failed") {
			telemetry.emit("reconnect.completed", { provider: "openai", attempt: Math.max(1, reconnectAttempt), outcome: "failed" });
			telemetry.emit("session.error", { provider: "openai", errorCode: "webrtc_connection_failed" });
			const error = protocolError(new Error("WebRTC transport failed"), "webrtc_connection_failed");
			canonical.emit("reconnect.failed", { attempt: Math.max(1, reconnectAttempt), error, retryable: false });
			canonical.emit("error", { error, fatal: true });
			complete("error");
		}
	});

	const dataChannel = pc.createDataChannel("oai-events");
	let responseActive = false;

	// The frame drip gives the model ambient context; look_at_screen lets it
	// deliberately check the learner's work at the moment it matters.
	const sessionTools = visionEnabled ? [...(tools ?? []), LOOK_AT_SCREEN_TOOL] : (tools ?? []);

	micStream = await attachMicrophone(pc);
	if (!micStream) {
		const error = new Error("Microphone unavailable for live voice.");
		telemetry.emit("connection.setup.completed", {
			provider: "openai", model, transport: "webrtc", outcome: "failed",
		}, telemetry.durationSince(setupStartedAt));
		telemetry.emit("session.error", { provider: "openai", errorCode: "microphone_unavailable" });
		canonical.emit("error", { error: protocolError(error, "microphone_unavailable"), fatal: true });
		complete("error");
		cleanup();
		throw error;
	}

	const send = (payload: Record<string, unknown>) => {
		if (dataChannel.readyState !== "open") return;
		try {
			dataChannel.send(JSON.stringify(payload));
		} catch (error) {
			console.warn("[keating:realtime] send failed", error);
		}
	};

	const sendFrame = (frame: CapturedFrame) => {
		send(realtimeImageItem(frame.dataUrl));
		framesSent += 1;
	};

	dataChannel.addEventListener("open", () => {
		// Re-sent even though the same config rode along with the SDP offer: the
		// update is idempotent and guarantees tools are registered before the
		// learner's first utterance.
		send(buildRealtimeSessionUpdate(settings, instructions, sessionTools));

		// Replay prior chat turns so the voice session continues the same
		// conversation instead of reintroducing itself.
		for (const turnItem of history ?? []) {
			if (turnItem.text.trim()) send(realtimeHistoryItem(turnItem));
		}

		if (visionEnabled && video) unsubscribeFrames = video.onFrame(sendFrame);

		setState("listening");
		telemetry.emit("connection.setup.completed", {
			provider: "openai", model, transport: "webrtc", outcome: "success",
		}, telemetry.durationSince(setupStartedAt));
	});

	dataChannel.addEventListener("message", (event) => {
		try {
			const msg = JSON.parse(event.data);
			switch (msg.type) {
			case "input_audio_buffer.speech_started":
				turn += 1;
				activeTurnStartedAt = telemetry.start();
				telemetry.emit("speech.turn.started", { provider: "openai", turn });
				if (responseActive) {
					dataChannel.send(JSON.stringify({ type: "response.cancel" }));
					dataChannel.send(JSON.stringify({ type: "output_audio_buffer.clear" }));
					responseActive = false;
					canonical.emit("conversation.interrupted", { by: "user", reason: "barge-in" });
					telemetry.emit("speech.interrupted", { provider: "openai", reason: "barge-in", turn });
				}
				setState("listening");
				break;
			case "response.created":
				responseActive = true;
				break;
			case "response.output_audio.delta":
				case "response.audio.delta":
					if (!firstAudioObserved) {
						firstAudioObserved = true;
						telemetry.emit("audio.first", { provider: "openai", transport: "webrtc" }, telemetry.durationSince(setupStartedAt));
					}
					setState("speaking");
					if (typeof msg.delta === "string") canonical.emit("audio.delta", {
						streamId: typeof msg.item_id === "string" ? `assistant-audio-${msg.item_id}` : "assistant-audio",
						messageId: typeof msg.item_id === "string" ? msg.item_id : undefined,
						role: "assistant",
						encoding: "pcm16",
						sampleRate: 24_000,
						data: msg.delta,
					});
					break;
				case "response.audio_transcript.delta":
				case "response.output_audio_transcript.delta":
					onAssistantTranscript?.(typeof msg.delta === "string" ? msg.delta : "", false);
					canonical.emit("transcript.delta", {
						transcriptId: typeof msg.item_id === "string" ? `assistant-transcript-${msg.item_id}` : "assistant-transcript",
						messageId: typeof msg.item_id === "string" ? msg.item_id : undefined,
						role: "assistant",
						delta: typeof msg.delta === "string" ? msg.delta : "",
						final: false,
					});
					break;
				case "response.audio_transcript.done":
				case "response.output_audio_transcript.done":
					onAssistantTranscript?.(typeof msg.transcript === "string" ? msg.transcript : "", true);
					canonical.emit("transcript.delta", {
						transcriptId: typeof msg.item_id === "string" ? `assistant-transcript-${msg.item_id}` : "assistant-transcript",
						messageId: typeof msg.item_id === "string" ? msg.item_id : undefined,
						role: "assistant", delta: "", final: true,
					});
					if (typeof msg.item_id === "string") canonical.emit("message.completed", { messageId: msg.item_id });
					break;
				case "conversation.item.input_audio_transcription.delta":
					onUserTranscript?.(typeof msg.delta === "string" ? msg.delta : "", false);
					canonical.emit("transcript.delta", {
						transcriptId: typeof msg.item_id === "string" ? `user-transcript-${msg.item_id}` : "user-transcript",
						messageId: typeof msg.item_id === "string" ? msg.item_id : undefined,
						role: "user", delta: typeof msg.delta === "string" ? msg.delta : "", final: false,
					});
					break;
				case "conversation.item.input_audio_transcription.completed":
					onUserTranscript?.(typeof msg.transcript === "string" ? msg.transcript : "", true);
					canonical.emit("transcript.delta", {
						transcriptId: typeof msg.item_id === "string" ? `user-transcript-${msg.item_id}` : "user-transcript",
						messageId: typeof msg.item_id === "string" ? msg.item_id : undefined,
						role: "user", delta: "", final: true,
					});
					if (typeof msg.item_id === "string") canonical.emit("message.completed", { messageId: msg.item_id });
					break;
			case "response.done":
				responseActive = false;
				setState("listening");
				telemetry.emit("speech.turn.completed", { provider: "openai", turn, outcome: "completed" },
					activeTurnStartedAt === null ? undefined : telemetry.durationSince(activeTurnStartedAt));
				activeTurnStartedAt = null;
				break;
			case "response.function_call_arguments.done": {
				if (typeof msg.name !== "string" || typeof msg.call_id !== "string") break;
				const call = {
					callId: msg.call_id,
					name: msg.name,
					arguments: parseToolArguments(msg.arguments),
				};
				void runLiveToolCall({
					call,
					provider: "openai",
					canonical,
					telemetry,
					execute: async (pending) => {
						// look_at_screen is served locally from the capture handle
						// rather than round-tripping through the agent tool catalog.
						if (pending.name === LOOK_AT_SCREEN_TOOL_NAME) {
							const frame = await video?.captureFrameNow();
							if (!frame) return { ok: false, error: "No video frame is available right now." };
							return { ok: true, note: "A current frame has been added to the conversation." };
						}
						if (!onToolCall) throw new Error(`No handler is available for tool ${pending.name}.`);
						return await onToolCall(pending);
					},
					respond: (callId, output) => {
						send(realtimeFunctionOutput(callId, output));
						send({ type: "response.create" });
					},
					respondError: (callId, message) => {
						send(realtimeFunctionOutput(callId, { error: message }));
						send({ type: "response.create" });
					},
				});
				break;
			}
				case "error":
					{
						const error = new Error(`Realtime error: ${msg.error?.message ?? "unknown"}`);
						onError?.(error);
						canonical.emit("error", { error: protocolError(error, "provider_error"), fatal: false });
						telemetry.emit("session.error", { provider: "openai", errorCode: "provider_error" });
					}
					break;
			}
		} catch (error) {
			canonical.emit("error", { error: protocolError(error, "invalid_provider_event"), fatal: false });
			telemetry.emit("session.error", { provider: "openai", errorCode: "invalid_provider_event" });
		}
	});

	try {
		getAudioContext();
		const offer = await pc.createOffer();
		await pc.setLocalDescription(offer);

}

async function startLiveSession(
	request: LiveSpeechRequest,
	observer?: RealtimeTelemetryObserver,
): Promise<LiveSpeechSession> {
	const {
		settings, getApiKey, signal, instructions, tools, history, video,
		onToolCall, onState, onUserTranscript, onAssistantTranscript, onError,
	} = request;

	const model = settings.model || GEMINI_LIVE_SPEECH_MODEL;
	const telemetry = createRealtimeTelemetry(observer);
	const canonical = createRealtimeCanonicalBridge(request.onConversationEvent, request.conversationIds);
	const setupStartedAt = telemetry.start();
	telemetry.emit("connection.setup.started", { provider: "google", model, transport: "websocket" });

	const capability = negotiateGeminiLiveSession(model);
	if (capability.realtimeAudio !== "native" || capability.transport !== "websocket" || capability.toolCalls !== "native") {
		telemetry.emit("session.error", { provider: "google", errorCode: "capability_mismatch" });
		telemetry.emit("session.completed", { provider: "google", outcome: "error" });
		throw new Error(`Gemini Live model ${model} cannot satisfy duplex audio and native tool-call requirements.`);
	}

	// Gemini has a real video lane, so frames go straight in at full tier.
	const visionEnabled = Boolean(video) && capability.realtimeVideo === "native";
	canonical.emit("run.started", { mode: visionEnabled ? "multimodal" : "voice" });

	const apiKey = await getApiKey("google");
	if (!apiKey) {
		const error = new Error("No Google API key configured. Sign in to Google in Settings → Providers & Models.");
		telemetry.emit("session.error", { provider: "google", errorCode: "missing_api_key" });
		telemetry.emit("session.completed", { provider: "google", outcome: "error" });
		canonical.emit("error", { error: protocolError(error, "missing_api_key"), fatal: true });
		canonical.emit("run.completed", { reason: "error" });
		throw error;
	}

	const { GoogleGenAI, Modality, MediaResolution } = await import("@google/genai");
	const ai = new GoogleGenAI({ apiKey });

	let state: LiveSpeechState = "connecting";
	let completionReason: "completed" | "cancelled" | "interrupted" | "error" | null = null;
	let firstAudioObserved = false;
	let turn = 0;
	let activeTurnStartedAt: number | null = null;
	let framesSent = 0;

	const complete = (reason: NonNullable<typeof completionReason>) => {
		if (completionReason) return;
		completionReason = reason;
		canonical.emit("run.completed", { reason });
		telemetry.emit("session.completed", { provider: "google", outcome: reason });
	};
	const setState = (next: LiveSpeechState) => {
		if (state === "closed") return;
		state = next;
		onState?.(next);
	};
	setState("connecting");

	let session: {
		sendRealtimeInput: (params: any) => void;
		sendClientContent: (params: any) => void;
		sendToolResponse: (params: any) => void;
		close: () => void;
	} | null = null;
	let capture: Awaited<ReturnType<typeof startPcmCapture>> | null = null;
	let unsubscribeFrames: (() => void) | null = null;
	let cleanedUp = false;

	const cleanup = () => {
		if (cleanedUp) return;
		cleanedUp = true;
		unsubscribeFrames?.();
		unsubscribeFrames = null;
		capture?.stop();
		capture = null;
		try { session?.close(); } catch {}
		setState("closed");
		complete("cancelled");
	};

	if (signal?.aborted) {
		canonical.emit("conversation.interrupted", { by: "host", reason: "abort signal before start" });
		telemetry.emit("speech.interrupted", { provider: "google", reason: "abort", turn });
		complete("interrupted");
		cleanup();
		throw new Error("Gemini Live aborted before start.");
	}
	signal?.addEventListener("abort", () => {
		canonical.emit("conversation.interrupted", { by: "host", reason: "abort signal" });
		telemetry.emit("speech.interrupted", { provider: "google", reason: "abort", turn });
		complete("interrupted");
		cleanup();
	}, { once: true });

	const handleToolCall = (functionCalls: any[]) => {
		for (const functionCall of functionCalls) {
			if (typeof functionCall?.name !== "string") continue;
			const callId = typeof functionCall.id === "string" ? functionCall.id : functionCall.name;
			void runLiveToolCall({
				call: { callId, name: functionCall.name, arguments: parseToolArguments(functionCall.args) },
				provider: "google",
				canonical,
				telemetry,
				execute: async (pending) => {
					if (!onToolCall) throw new Error(`No handler is available for tool ${pending.name}.`);
					return await onToolCall(pending);
				},
				respond: (id, output) => {
					session?.sendToolResponse({
						functionResponses: [geminiFunctionResponse(id, functionCall.name, output, model)],
					});
				},
				respondError: (id, message) => {
					session?.sendToolResponse({
						functionResponses: [geminiFunctionResponse(id, functionCall.name, message, model, { failed: true })],
					});
				},
			});
		}
	};

	try {
		session = await withApiRetry(() => ai.live.connect({
			model,
			callbacks: {
				onmessage: (message: any) => {
					// Barge-in: the server cancels generation when the learner
					// speaks over the model. Queued PCM must be dropped too, or
					// the learner keeps hearing the sentence they interrupted.
					if (message?.serverContent?.interrupted) {
						stopScheduledAudio();
						canonical.emit("conversation.interrupted", { by: "user", reason: "barge-in" });
						telemetry.emit("speech.interrupted", { provider: "google", reason: "barge-in", turn });
						setState("listening");
					}

					if (Array.isArray(message?.toolCall?.functionCalls)) {
						handleToolCall(message.toolCall.functionCalls);
					}

					for (const part of contentParts(message)) {
						const data = part.inlineData?.data;
						if (typeof data === "string" && data.length > 0) {
							if (!firstAudioObserved) {
								firstAudioObserved = true;
								telemetry.emit("audio.first", { provider: "google", transport: "websocket" },
									telemetry.durationSince(setupStartedAt));
							}
							setState("speaking");
							schedulePcmAudio(data);
							canonical.emit("audio.delta", {
								streamId: "assistant-audio",
								role: "assistant",
								encoding: "pcm16",
								sampleRate: 24_000,
								data,
							});
						}
						if (typeof part.text === "string") {
							onAssistantTranscript?.(part.text, false);
							canonical.emit("transcript.delta", {
								transcriptId: "assistant-transcript",
								role: "assistant",
								delta: part.text,
								final: false,
							});
						}
					}

					const outputText = message?.serverContent?.outputTranscription?.text;
					if (typeof outputText === "string") {
						onAssistantTranscript?.(outputText, false);
						canonical.emit("transcript.delta", {
							transcriptId: "assistant-transcript",
							role: "assistant",
							delta: outputText,
							final: false,
						});
					}

					const inputText = message?.serverContent?.inputTranscription?.text;
					if (typeof inputText === "string") {
						if (activeTurnStartedAt === null) {
							turn += 1;
							activeTurnStartedAt = telemetry.start();
							telemetry.emit("speech.turn.started", { provider: "google", turn });
						}
						onUserTranscript?.(inputText, false);
						canonical.emit("transcript.delta", {
							transcriptId: "user-transcript",
							role: "user",
							delta: inputText,
							final: false,
						});
					}

					if (message?.serverContent?.turnComplete) {
						onAssistantTranscript?.("", true);
						canonical.emit("transcript.delta", {
							transcriptId: "assistant-transcript",
							role: "assistant",
							delta: "",
							final: true,
						});
						telemetry.emit("speech.turn.completed", { provider: "google", turn, outcome: "completed" },
							activeTurnStartedAt === null ? undefined : telemetry.durationSince(activeTurnStartedAt));
						activeTurnStartedAt = null;
						setState("listening");
					}
				},
				onerror: (event: ErrorEvent) => {
					const error = new Error(event.message || "Gemini Live failed.");
					onError?.(error);
					canonical.emit("error", { error: protocolError(error, "provider_error"), fatal: false });
					telemetry.emit("session.error", { provider: "google", errorCode: "provider_error" });
				},
				onclose: () => cleanup(),
			},
			config: {
				responseModalities: [Modality.AUDIO],
				outputAudioTranscription: {},
				inputAudioTranscription: {},
				speechConfig: {
					voiceConfig: { prebuiltVoiceConfig: { voiceName: settings.voiceName || "Kore" } },
				},
				// Frames are already downscaled client-side; low resolution keeps
				// the token cost of continuous vision manageable.
				...(visionEnabled ? { mediaResolution: MediaResolution.MEDIA_RESOLUTION_LOW } : {}),
				...(buildGeminiToolConfig(tools ?? [], model) ? { tools: buildGeminiToolConfig(tools ?? [], model) } : {}),
				systemInstruction:
					instructions ||
					"You are Keating, a warm Socratic tutor on a live voice call with a learner. Keep replies natural, concise, and conversational.",
			},
		}), { signal });
	} catch (error) {
		telemetry.emit("connection.setup.completed", {
			provider: "google", model, transport: "websocket", outcome: "failed",
		}, telemetry.durationSince(setupStartedAt));
		telemetry.emit("session.error", { provider: "google", errorCode: "session_setup_failed" });
		canonical.emit("error", { error: protocolError(error, "session_setup_failed"), fatal: true });
		complete("error");
		cleanup();
		throw error;
	}

	// Replay prior chat turns so the voice session continues the conversation
	// rather than reintroducing itself.
	const seedTurns = (history ?? []).filter((entry) => entry.text.trim());
	if (seedTurns.length > 0) {
		try {
			session.sendClientContent({ turns: seedTurns.map(geminiHistoryTurn), turnComplete: false });
		} catch (error) {
			console.warn("[keating:gemini-live] history seed failed", error);

/** A prior chat turn, replayed into a live session so voice continues the conversation. */
export interface LiveHistoryTurn {
	role: "user" | "assistant";
	text: string;
}

export interface LiveSpeechBridge {
	tools: LiveSpeechTool[];
	execute(call: LiveSpeechToolCall, signal?: AbortSignal): Promise<unknown>;
	/**
	 * The real Keating system prompt, so the voice session is the same teacher
	 * as the text session rather than a generic assistant.
	 */
	instructions?: string;
	/** Recent conversation turns, oldest first. */
	history?: LiveHistoryTurn[];
}

export function getLiveSpeechBridge(): LiveSpeechBridge | undefined {
	if (typeof window === "undefined") return undefined;
	const detail: { bridge?: LiveSpeechBridge } = {};
	window.dispatchEvent(new CustomEvent("keating:live-speech-bridge", { detail }));
	return detail.bridge;
}

export interface LiveSpeechRequest {
	settings: WebSpeechSettings;
	customModel?: CustomSpeechModel;
	getApiKey: (provider: string) => Promise<string | undefined>;
	signal?: AbortSignal;
	/** Optional persona / system instructions for the live voice agent. */
	instructions?: string;
	/** Prior conversation turns to seed the session with, oldest first. */
	history?: LiveHistoryTurn[];
	/**
	 * An already-running frame source. The caller owns capture so the same
	 * MediaStream can be previewed in the UI; the provider only consumes frames
	 * and routes them however its tier allows.
	 */
	video?: VideoCaptureHandle | null;
	onState?: (state: LiveSpeechState) => void;
	onUserTranscript?: (text: string, final: boolean) => void;
	onAssistantTranscript?: (text: string, final: boolean) => void;
	tools?: LiveSpeechTool[];
	onToolCall?: (call: LiveSpeechToolCall) => Promise<unknown>;
	onError?: (error: Error) => void;
	/** Optional provider-neutral event stream for persistence, replay, and alternate UIs. */
	onConversationEvent?: (event: ConversationEvent) => void;
	/** Stable identifiers supplied by a host that is continuing an existing conversation. */
	conversationIds?: { sessionId?: string; runId?: string };
}

export interface LiveSpeechSession {
	readonly state: LiveSpeechState;
	/** Frames delivered to the model so far, for the live HUD. */
	readonly framesSent?: number;
	/** How vision reached the model in this session, if at all. */
	readonly videoRoute?: "native" | "sampled" | "none";
	stop(): Promise<void>;
}

export interface SpeechProvider extends SpeechProviderDescriptor {
	synthesize(request: SpeechSynthesisRequest): Promise<SpeechSynthesisResult>;
	/** Opens a long-lived bidirectional voice session (duplex providers only). */
	startLiveSession?(request: LiveSpeechRequest): Promise<LiveSpeechSession>;
}

const providerRegistry = new Map<SpeechProviderId, SpeechProvider>();
let registrationPromise: Promise<void> | null = null;

async function ensureProvidersRegistered(): Promise<void> {
	if (registrationPromise) return registrationPromise;
	registrationPromise = (async () => {
		const [gemini, oaiTts, oaiRealtime, supertonic] = await Promise.all([
			import("./speech-providers/gemini-live"),
			import("./speech-providers/openai-tts"),
			import("./speech-providers/openai-realtime"),
			import("./speech-providers/supertonic"),
		]);
		providerRegistry.set("gemini-live", gemini.geminiLiveProvider);
		providerRegistry.set("openai-tts", oaiTts.openAITtsProvider);
		providerRegistry.set("openai-realtime", oaiRealtime.openAIRealtimeProvider);
		providerRegistry.set("supertonic-3", supertonic.supertonicProvider);
	})();
	return registrationPromise;
}

export async function listSpeechProviders(): Promise<SpeechProviderDescriptor[]> {
	await ensureProvidersRegistered();
	return Array.from(providerRegistry.values()).map(({ synthesize: _ignored, ...info }) => info);
}

export async function getSpeechProvider(id: SpeechProviderId): Promise<SpeechProvider | null> {
	await ensureProvidersRegistered();
	return providerRegistry.get(id) ?? null;

